"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import React from "react"

import {
  TableColumnSliderFilterOptions,
  TableColumnSliderFilterMenu,
} from "../filters/table-column-slider-filter"
import { useColumnHeaderContext } from "./data-table-column-header"

import type { DataTableColumn } from "../types"
import type { RowData } from "@tanstack/react-table"
/**
 * Slider filter options for composing inside DataTableColumnActions using context.
 */
export function DataTableColumnSliderFilterOptions<
  TData extends RowData,
  TValue,
>(
  props: Omit<
    React.ComponentProps<typeof TableColumnSliderFilterOptions>,
    "column"
  > & {
    column?: DataTableColumn<TData, TValue>
  },
) {
  const context = useColumnHeaderContext<TData, TValue>(false)
  const column = props.column || context?.column

  if (!column) {
    console.warn(
      "DataTableColumnSliderFilterOptions must be used within DataTableColumnHeaderRoot or provided with a column prop",
    )
    return null
  }

  return <TableColumnSliderFilterOptions column={column} {...props} />
}

DataTableColumnSliderFilterOptions.displayName =
  "DataTableColumnSliderFilterOptions"

/**
 * Standalone slider filter menu for column header using context.
 */
export function DataTableColumnSliderFilterMenu<TData extends RowData, TValue>(
  props: Omit<
    React.ComponentProps<typeof TableColumnSliderFilterMenu>,
    "column"
  > & {
    column?: DataTableColumn<TData, TValue>
  },
) {
  const context = useColumnHeaderContext<TData, TValue>(false)
  const column = props.column || context?.column

  if (!column) {
    console.warn(
      "DataTableColumnSliderFilterMenu must be used within DataTableColumnHeaderRoot or provided with a column prop",
    )
    return null
  }

  return <TableColumnSliderFilterMenu column={column} {...props} />
}

DataTableColumnSliderFilterMenu.displayName = "DataTableColumnSliderFilterMenu"

"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import React from "react"
import { CircleHelp, SlidersHorizontal } from "lucide-react"

import {
  DropdownMenuSeparator,
  DropdownMenuLabel,
  DropdownMenuPanel,
} from "@/components/niko-table/primitives/dropdown-menu"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/niko-table/primitives/popover"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/niko-table/primitives/tooltip"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/niko-table/primitives/button"
import { Slider } from "@/components/niko-table/primitives/slider"
import { cn } from "@/lib/utils"
import { useDerivedColumnTitle } from "../hooks/use-derived-column-title"

import type { DataTableColumn } from "../types"
import type { RowData } from "@tanstack/react-table"
type RangeValue = [number, number]

function parseValuesAsNumbers(value: unknown): RangeValue | undefined {
  if (
    Array.isArray(value) &&
    value.length === 2 &&
    value.every(
      v => (typeof v === "string" || typeof v === "number") && !Number.isNaN(v),
    )
  ) {
    return [Number(value[0]), Number(value[1])]
  }

  return undefined
}

function getIsValidRange(value: unknown): value is RangeValue {
  return (
    Array.isArray(value) &&
    value.length === 2 &&
    typeof value[0] === "number" &&
    typeof value[1] === "number"
  )
}

/**
 * Slider filter options for composing inside TableColumnActions.
 * Renders as inline slider with min/max inputs.
 *
 * @example
 * ```tsx
 * // Inside TableColumnActions
 * <TableColumnActions column={column}>
 *   <TableColumnSliderFilterOptions
 *     column={column}
 *     min={0}
 *     max={1000}
 *   />
 * </TableColumnActions>
 * ```
 */
export function TableColumnSliderFilterOptions<TData extends RowData, TValue>({
  column,
  title,
  range: manualRange,
  min: manualMin,
  max: manualMax,
  step: manualStep,
  unit: manualUnit,
  onValueChange,
  withSeparator = true,
}: {
  column: DataTableColumn<TData, TValue>
  title?: string
  /**
   * Manual range [min, max] (overrides min/max props and column.meta.range)
   */
  range?: RangeValue
  /**
   * Manual minimum value (overrides column.meta.range and faceted values)
   */
  min?: number
  /**
   * Manual maximum value (overrides column.meta.range and faceted values)
   */
  max?: number
  /**
   * Manual step value for the slider
   */
  step?: number
  /**
   * Unit label to display (e.g., "$", "kg", "km")
   */
  unit?: string
  onValueChange?: (value: [number, number] | undefined) => void
  /** Whether to render a separator before the options. Defaults to true. */
  withSeparator?: boolean
}) {
  const id = React.useId()

  const columnFilterValue = parseValuesAsNumbers(column.getFilterValue())

  const defaultRange = column.columnDef.meta?.range
  const unit = manualUnit ?? column.columnDef.meta?.unit

  // Capture faceted min/max as scalars so the memo re-runs when filters/data change.
  const facetedValues = column.getFacetedMinMaxValues()
  const facetedMin = facetedValues?.[0]
  const facetedMax = facetedValues?.[1]

  // Compute range values - memoized to avoid recalculation
  const { min, max, step } = React.useMemo<{
    min: number
    max: number
    step: number
  }>(() => {
    let minValue = 0
    let maxValue = 100

    // Priority 1: Manual range prop (highest priority)
    if (manualRange && getIsValidRange(manualRange)) {
      minValue = manualRange[0]
      maxValue = manualRange[1]
    }
    // Priority 2: Manual min/max props
    else if (manualMin != null && manualMax != null) {
      minValue = manualMin
      maxValue = manualMax
    }
    // Priority 3: Use explicit range from column metadata
    else if (defaultRange && getIsValidRange(defaultRange)) {
      minValue = defaultRange[0]
      maxValue = defaultRange[1]
    }
    // Priority 4: Get min/max from faceted values
    else if (facetedMin != null && facetedMax != null) {
      minValue = Number(facetedMin)
      maxValue = Number(facetedMax)
    }

    // Calculate appropriate step size based on range
    const rangeSize = maxValue - minValue
    const calculatedStep =
      rangeSize <= 20
        ? 1
        : rangeSize <= 100
          ? Math.ceil(rangeSize / 20)
          : Math.ceil(rangeSize / 50)

    return {
      min: minValue,
      max: maxValue,
      step: manualStep ?? calculatedStep,
    }
  }, [
    defaultRange,
    manualRange,
    manualMin,
    manualMax,
    manualStep,
    facetedMin,
    facetedMax,
  ])

  const range = React.useMemo((): RangeValue => {
    return columnFilterValue ?? [min, max]
  }, [columnFilterValue, min, max])

  const derivedTitle = useDerivedColumnTitle(column, column.id, title)
  const labelText = "Range Filter"
  const tooltipText = "Set a range to filter values"

  const applyFilterValue = React.useCallback(
    (value: [number, number] | undefined) => {
      column.setFilterValue(value)
      onValueChange?.(value)
    },
    [column, onValueChange],
  )

  const onRangeValueChange = React.useCallback(
    (value: string | number, isMin?: boolean) => {
      const numValue = Number(value)
      const currentValues = range

      if (value === "") {
        // Allow empty value, don't update filter
        return
      }

      if (
        !Number.isNaN(numValue) &&
        (isMin
          ? numValue >= min && numValue <= currentValues[1]
          : numValue <= max && numValue >= currentValues[0])
      ) {
        applyFilterValue(
          isMin ? [numValue, currentValues[1]] : [currentValues[0], numValue],
        )
      }
    },
    [min, max, range, applyFilterValue],
  )

  const onSliderValueChange = React.useCallback(
    // Radix sliders emit number[]; Base UI emits number | readonly number[]
    (value: RangeValue | number | readonly number[]) => {
      if (Array.isArray(value) && value.length === 2) {
        applyFilterValue([value[0], value[1]])
      }
    },
    [applyFilterValue],
  )

  const onReset = React.useCallback(() => {
    applyFilterValue(undefined)
  }, [applyFilterValue])

  return (
    <>
      {withSeparator && <DropdownMenuSeparator />}
      <DropdownMenuLabel className="flex items-center justify-between text-xs font-normal text-muted-foreground">
        <span>{labelText}</span>
        <Tooltip>
          <TooltipTrigger asChild>
            <CircleHelp className="size-3.5 cursor-help" />
          </TooltipTrigger>
          <TooltipContent side="right">
            {tooltipText}
            {derivedTitle && ` - ${derivedTitle}`}
          </TooltipContent>
        </Tooltip>
      </DropdownMenuLabel>
      <DropdownMenuPanel>
        <div className="px-2 py-2">
          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-2">
              <Label htmlFor={`${id}-from`} className="sr-only">
                From
              </Label>
              <div className="relative flex-1">
                <Input
                  key={`${id}-from-${range[0]}`}
                  id={`${id}-from`}
                  type="number"
                  aria-label={`${derivedTitle} minimum value`}
                  aria-valuemin={min}
                  aria-valuemax={max}
                  inputMode="numeric"
                  pattern="[0-9]*"
                  placeholder={min.toString()}
                  min={min}
                  max={max}
                  defaultValue={range[0]}
                  onChange={event =>
                    onRangeValueChange(String(event.target.value), true)
                  }
                  className={cn("h-8 w-full", unit && "pr-8")}
                />
                {unit && (
                  <span className="absolute top-0 right-0 bottom-0 mt-0.5 mr-0.5 flex h-7 items-center rounded-r-md bg-accent px-2 text-sm text-muted-foreground">
                    {unit}
                  </span>
                )}
              </div>
              <Label htmlFor={`${id}-to`} className="sr-only">
                to
              </Label>
              <div className="relative flex-1">
                <Input
                  key={`${id}-to-${range[1]}`}
                  id={`${id}-to`}
                  type="number"
                  aria-label={`${derivedTitle} maximum value`}
                  aria-valuemin={min}
                  aria-valuemax={max}
                  inputMode="numeric"
                  pattern="[0-9]*"
                  placeholder={max.toString()}
                  min={min}
                  max={max}
                  defaultValue={range[1]}
                  onChange={event =>
                    onRangeValueChange(String(event.target.value))
                  }
                  className={cn("h-8 w-full", unit && "pr-8")}
                />
                {unit && (
                  <span className="absolute top-0 right-0 bottom-0 mt-0.5 mr-0.5 flex h-7 items-center rounded-r-md bg-accent px-2 text-sm text-muted-foreground">
                    {unit}
                  </span>
                )}
              </div>
            </div>
            <Label htmlFor={`${id}-slider`} className="sr-only">
              {derivedTitle} slider
            </Label>
            <Slider
              id={`${id}-slider`}
              min={min}
              max={max}
              step={step}
              value={range}
              onValueChange={onSliderValueChange}
              className="w-full"
            />
            <Button
              aria-label={`Clear ${derivedTitle} filter`}
              variant="outline"
              size="sm"
              onClick={onReset}
              className="w-full"
            >
              Clear
            </Button>
          </div>
        </div>
      </DropdownMenuPanel>
    </>
  )
}

TableColumnSliderFilterOptions.displayName = "TableColumnSliderFilterOptions"

/**
 * Standalone slider filter menu for column headers.
 * Shows a filter button that opens a popover with a range slider.
 *
 * @example
 * ```tsx
 * // Standalone usage
 * <TableColumnSliderFilterMenu
 *   column={column}
 *   min={0}
 *   max={1000}
 * />
 * ```
 */
export function TableColumnSliderFilterMenu<TData extends RowData, TValue>({
  column,
  title,
  className,
  ...props
}: Omit<
  React.ComponentProps<typeof TableColumnSliderFilterOptions>,
  "withSeparator" | "column"
> & {
  column: DataTableColumn<TData, TValue>
  className?: string
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className={cn(
            "size-7 transition-opacity dark:text-muted-foreground",
            column.getIsFiltered() && "text-primary",
            className,
          )}
        >
          <SlidersHorizontal className="size-3.5" />
          <span className="sr-only">Filter by range</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-52 p-0">
        <TableColumnSliderFilterOptions
          column={column}
          title={title}
          withSeparator={false}
          {...props}
        />
      </PopoverContent>
    </Popover>
  )
}

TableColumnSliderFilterMenu.displayName = "TableColumnSliderFilterMenu"

"use client"

/**
 * Niko Table's popover primitive, React Aria build. Radix-shaped API
 * (`Popover open onOpenChange`, `PopoverTrigger asChild`, `PopoverContent
 * align side sideOffset`) on shadcn's React Aria `PopoverTrigger` (React Aria
 * `DialogTrigger`, which owns the open state) and `Popover`.
 *
 * `PopoverTrigger asChild` hands the press to its child, which must be the
 * Button primitive (or shadcn's Button), as with shadcn's own trigger.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
} from "react-aria-components"

import {
  Popover as PopoverPrimitive,
  PopoverTrigger as PopoverRoot,
} from "@/components/ui/popover"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

function useDataState() {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  return isOpen ? "open" : "closed"
}

function Popover({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria popovers are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <PopoverRoot
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </PopoverRoot>
  )
}

function PopoverTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const state = { "data-state": useDataState() }
  if (asChild && React.isValidElement<object>(children))
    // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
    return React.cloneElement(
      children,
      mergeProps(children.props, props, state),
    )
  return (
    <Pressable>
      <button type="button" {...props} {...state}>
        {children}
      </button>
    </Pressable>
  )
}

function PopoverContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  id,
  className,
  children,
  ...props
}: Omit<
  React.ComponentProps<typeof PopoverPrimitive>,
  | "children"
  | "className"
  | "placement"
  | "offset"
  | "crossOffset"
  | "isOpen"
  | "onOpenChange"
  | "triggerRef"
> & {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  /** Radix puts it on the popup; React Aria's popover takes no `id`. */
  id?: string
  className?: string
  children?: React.ReactNode
}) {
  return (
    <PopoverPrimitive
      {...props}
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
      data-state={useDataState()}
    >
      {id ? (
        <div id={id} className="contents">
          {children}
        </div>
      ) : (
        children
      )}
    </PopoverPrimitive>
  )
}

export { Popover, PopoverContent, PopoverTrigger }

"use client"

/**
 * Niko Table's tooltip primitive, React Aria build. Radix-shaped API
 * (`TooltipProvider`, `Tooltip`, `TooltipTrigger asChild`, `TooltipContent
 * side`) on shadcn's React Aria `TooltipTrigger` (which makes the first child
 * focusable) and `Tooltip` popup.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { Placement } from "react-aria-components"

import {
  Tooltip as TooltipPopup,
  TooltipTrigger as TooltipRoot,
} from "@/components/ui/tooltip"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

/**
 * Pass-through. React Aria has no tooltip provider; it is kept because the
 * shared Niko Table source wraps tables in one for Radix and Base UI. Its delay
 * is ignored: tooltips use shadcn's per-tooltip `delay` (`delayDuration` on
 * `Tooltip`).
 */
function TooltipProvider({
  children,
}: {
  /** Radix name. */
  delayDuration?: number
  /** Base UI name; accepted so a spread of both typechecks. */
  delay?: number
  children?: React.ReactNode
}) {
  return children
}

function Tooltip({
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  delayDuration?: number
  children?: React.ReactNode
}) {
  return (
    <TooltipRoot
      delay={delayDuration}
      closeDelay={0}
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </TooltipRoot>
  )
}

/** Slot: shadcn's TooltipTrigger passes its focus props and ref here. */
function TooltipTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  if (asChild && React.isValidElement<object>(children))
    return React.cloneElement(children, mergeProps(children.props, props))
  return (
    <button type="button" {...props}>
      {children}
    </button>
  )
}

function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  side?: Side
  align?: Align
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <TooltipPopup
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </TooltipPopup>
  )
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger }

"use client"

/**
 * Niko Table's dropdown-menu primitive, React Aria build. Radix-shaped API
 * (`DropdownMenuTrigger asChild`, `DropdownMenuContent align side`, items with
 * `onClick` / `disabled` / `variant`, submenus, radio groups) on top of
 * `react-aria-components` `MenuTrigger` / `Pressable` and the React Aria shadcn
 * dropdown-menu pieces (a React Aria `Menu` in a `Popover`).
 *
 * A React Aria menu is a collection: only items, labels, separators, groups
 * and submenus render inside it. Wrap any other content in
 * `DropdownMenuPanel`, which renders it as a non-focusable menu node.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  Header,
  MenuTrigger,
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
  type PressEvent,
} from "react-aria-components"

import {
  DropdownMenu as MenuPopover,
  DropdownMenuGroup,
  DropdownMenuItem as MenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent as SubmenuPopover,
  DropdownMenuSubTrigger as SubmenuItem,
} from "@/components/ui/dropdown-menu"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function DropdownMenu({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria menus are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <MenuTrigger
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </MenuTrigger>
  )
}

function DropdownMenuTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  const state = { "data-state": isOpen ? "open" : "closed" }
  // Slot: MenuTrigger hands its press, keyboard and aria props to the child,
  // which must be the Button primitive (or shadcn's Button), as with shadcn's
  // own trigger. The trigger's own props merge onto it.
  if (asChild && React.isValidElement<object>(children))
    return React.cloneElement(
      children,
      mergeProps(children.props, props, state),
    )
  return (
    <Pressable>
      <button type="button" {...props} {...state}>
        {children}
      </button>
    </Pressable>
  )
}

function DropdownMenuContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <MenuPopover
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </MenuPopover>
  )
}

interface DropdownMenuItemProps {
  /** Runs on pointer and keyboard activation; the press event carries `shiftKey`. */
  onClick?: (event: PressEvent) => void
  disabled?: boolean
  variant?: "default" | "destructive"
  inset?: boolean
  textValue?: string
  className?: string
  children?: React.ReactNode
}

function DropdownMenuItem({
  onClick,
  disabled,
  textValue,
  children,
  ...props
}: DropdownMenuItemProps) {
  return (
    <MenuItem
      {...props}
      onPress={onClick}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function DropdownMenuSubTrigger({
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant">) {
  return (
    <SubmenuItem
      {...props}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </SubmenuItem>
  )
}

function DropdownMenuSubContent({
  sideOffset,
  alignOffset,
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  sideOffset?: number
  alignOffset?: number
}) {
  return (
    <SubmenuPopover
      // Unset keeps the shadcn aria submenu defaults.
      {...(sideOffset === undefined ? {} : { offset: sideOffset })}
      {...(alignOffset === undefined ? {} : { crossOffset: alignOffset })}
      className={className}
    >
      {children}
    </SubmenuPopover>
  )
}

function DropdownMenuRadioGroup({
  value,
  onValueChange,
  children,
}: {
  value?: string
  onValueChange?: (value: string) => void
  children?: React.ReactNode
}) {
  return (
    <DropdownMenuGroup
      selectionMode="single"
      disallowEmptySelection
      selectedKeys={value === undefined ? [] : [value]}
      onSelectionChange={keys => {
        if (keys === "all") return
        const [key] = keys
        if (key !== undefined) onValueChange?.(String(key))
      }}
    >
      {children}
    </DropdownMenuGroup>
  )
}

function DropdownMenuRadioItem({
  value,
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant"> & { value: string }) {
  return (
    <MenuItem
      {...props}
      id={value}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function stopMenuKeys(event: React.KeyboardEvent) {
  // Keep typing / arrows inside the panel's own controls; Escape still closes.
  if (event.key !== "Escape") event.stopPropagation()
}

function DropdownMenuPanel({ children }: { children: React.ReactNode }) {
  return (
    <Header
      role="presentation"
      onKeyDown={stopMenuKeys}
      onKeyUp={stopMenuKeys}
      // The menu moves focus to its first item when focus enters it.
      onFocus={event => event.stopPropagation()}
    >
      {children}
    </Header>
  )
}

export {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPanel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
}

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button }

"use client"

/**
 * Niko Table's slider primitive, React Aria build. Radix-shaped API (`value`
 * and `onValueChange` as arrays, `min` / `max` / `step`, `disabled`) on top of
 * the React Aria shadcn `Slider`.
 */
import * as React from "react"

import { Slider as SliderPrimitive } from "@/components/ui/slider"

function Slider({
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  min,
  max,
  disabled,
  ...props
}: Omit<
  React.ComponentProps<typeof SliderPrimitive>,
  | "value"
  | "defaultValue"
  | "onChange"
  | "onChangeEnd"
  | "isDisabled"
  | "minValue"
  | "maxValue"
> & {
  value?: readonly number[]
  defaultValue?: readonly number[]
  onValueChange?: (value: number[]) => void
  onValueCommit?: (value: number[]) => void
  min?: number
  max?: number
  disabled?: boolean
}) {
  const toArray = (next: number | number[]) =>
    Array.isArray(next) ? next : [next]
  return (
    <SliderPrimitive
      {...props}
      value={value ? [...value] : undefined}
      defaultValue={defaultValue ? [...defaultValue] : undefined}
      onChange={next => onValueChange?.(toArray(next))}
      onChangeEnd={next => onValueCommit?.(toArray(next))}
      minValue={min}
      maxValue={max}
      isDisabled={disabled}
    />
  )
}

export { Slider }
